[metadata] {"type": "create", "filePath": "/app/output/poster.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8">
<title>Large Language Models in Medicine - Academic Poster</title>
<style>
  @import url('https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700;800;900&display=swap');

  *, *::before, *::after { margin: 0; padding: 0; box-sizing: border-box; }

  :root {
    --navy: #1B2A4A;
    --navy-light: #2A3F6A;
    --teal: #3D7A8A;
    --teal-light: #5A9BAB;
    --teal-bg: #E8F4F7;
    --white: #FFFFFF;
    --off-white: #F8FAFB;
    --gray-100: #F3F4F6;
    --gray-200: #E5E7EB;
    --gray-300: #D1D5DB;
    --gray-500: #6B7280;
    --gray-700: #374151;
    --gray-900: #111827;
    --accent: #D4763A;
    --accent-light: #E8945E;
    --accent-bg: #FDF0EB;
    --accent-border: #E8A882;
  }

  body {
    font-family: 'Inter', -apple-system, BlinkMacSystemFont, sans-serif;
    background: var(--white);
    color: var(--gray-900);
    width: 2480px;
    overflow-x: hidden;
  }

  .poster {
    width: 2480px;
    min-height: 3510px;
    padding: 0;
    background: var(--white);
    display: flex;
    flex-direction: column;
  }

  /* ── HEADER ── */
  .header {
    background: var(--navy);
    color: var(--white);
    padding: 72px 80px 64px;
    position: relative;
    overflow: hidden;
  }
  .header::after {
    content: '';
    position: absolute;
    bottom: 0; left: 0; right: 0;
    height: 8px;
    background: linear-gradient(90deg, var(--teal), var(--teal-light), var(--accent));
  }
  .header .conference {
    font-size: 24px;
    font-weight: 500;
    letter-spacing: 3px;
    text-transform: uppercase;
    color: var(--teal-light);
    margin-bottom: 24px;
  }
  .header h1 {
    font-size: 72px;
    font-weight: 800;
    line-height: 1.1;
    max-width: 90%;
    margin-bottom: 28px;
    letter-spacing: -1px;
  }
  .header .subtitle {
    font-size: 28px;
    font-weight: 300;
    line-height: 1.5;
    color: rgba(255,255,255,0.8);
    max-width: 85%;
  }

  /* ── METRICS ROW ── */
  .metrics-row {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 0;
    background: var(--off-white);
    border-bottom: 3px solid var(--gray-200);
  }
  .metric-card {
    padding: 48px 40px;
    text-align: center;
    border-right: 2px solid var(--gray-200);
    position: relative;
  }
  .metric-card:last-child { border-right: none; }
  .metric-card .value {
    font-size: 96px;
    font-weight: 900;
    line-height: 1;
    margin-bottom: 12px;
    letter-spacing: -2px;
  }
  .metric-card .label {
    font-size: 22px;
    font-weight: 600;
    text-transform: uppercase;
    letter-spacing: 1.5px;
    margin-bottom: 12px;
  }
  .metric-card .context {
    font-size: 18px;
    font-weight: 400;
    line-height: 1.5;
    color: var(--gray-500);
    max-width: 90%;
    margin: 0 auto;
  }
  .metric-card.teal .value { color: var(--teal); }
  .metric-card.teal .label { color: var(--navy); }
  .metric-card.navy .value { color: var(--navy); }
  .metric-card.navy .label { color: var(--navy); }
  .metric-card.accent .value { color: var(--accent); }
  .metric-card.accent .label { color: var(--accent); }
  .metric-card.accent .context { color: #9A5A30; }
  .metric-card.accent { background: var(--accent-bg); }

  /* ── CONTENT AREA ── */
  .content {
    flex: 1;
    display: flex;
    flex-direction: column;
    padding: 0;
  }

  /* ── TWO-COLUMN ROW ── */
  .two-col {
    display: grid;
    grid-template-columns: 1fr 1fr;
    min-height: 0;
  }

  /* ── SECTION PANELS ── */
  .panel {
    padding: 52px 64px;
    border-bottom: 2px solid var(--gray-200);
    position: relative;
  }
  .panel.overview-panel {
    border-right: 2px solid var(--gray-200);
  }
  .panel h2 {
    font-size: 36px;
    font-weight: 700;
    color: var(--navy);
    margin-bottom: 28px;
    padding-bottom: 16px;
    border-bottom: 4px solid var(--teal);
    display: inline-block;
  }
  .panel p {
    font-size: 22px;
    line-height: 1.7;
    color: var(--gray-700);
  }

  /* ── APPLICATIONS ── */
  .app-grid {
    display: grid;
    grid-template-columns: 1fr;
    gap: 16px;
    margin-top: 8px;
  }
  .app-item {
    display: flex;
    align-items: flex-start;
    gap: 20px;
    padding: 20px 24px;
    background: var(--off-white);
    border-radius: 12px;
    border-left: 5px solid var(--teal);
    transition: background 0.2s;
  }
  .app-item .app-icon {
    width: 48px;
    height: 48px;
    border-radius: 10px;
    background: var(--teal-bg);
    display: flex;
    align-items: center;
    justify-content: center;
    flex-shrink: 0;
    font-size: 22px;
  }
  .app-item .app-body h3 {
    font-size: 22px;
    font-weight: 600;
    color: var(--navy);
    margin-bottom: 4px;
  }
  .app-item .app-body .app-desc {
    font-size: 18px;
    color: var(--gray-500);
    line-height: 1.4;
  }
  .app-item .maturity {
    font-size: 15px;
    font-weight: 600;
    text-transform: uppercase;
    letter-spacing: 1px;
    color: var(--teal);
    background: var(--teal-bg);
    padding: 4px 12px;
    border-radius: 20px;
    white-space: nowrap;
    margin-top: 4px;
    display: inline-block;
  }

  /* ── PERFORMANCE SECTION ── */
  .performance-section {
    padding: 52px 64px;
    border-bottom: 2px solid var(--gray-200);
  }
  .performance-section h2 {
    font-size: 36px;
    font-weight: 700;
    color: var(--navy);
    margin-bottom: 28px;
    padding-bottom: 16px;
    border-bottom: 4px solid var(--teal);
    display: inline-block;
  }
  .perf-container {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 48px;
    align-items: start;
  }
  .perf-chart-area {
    min-height: 360px;
  }
  .perf-chart-area .chart-wrapper {
    width: 100%;
    height: 360px;
  }
  .perf-text {
    padding-top: 12px;
  }
  .perf-text p {
    font-size: 22px;
    line-height: 1.7;
    color: var(--gray-700);
    margin-bottom: 20px;
  }
  .perf-highlight {
    display: flex;
    align-items: center;
    gap: 16px;
    padding: 20px 24px;
    background: var(--teal-bg);
    border-radius: 12px;
    margin-bottom: 16px;
  }
  .perf-highlight .ph-value {
    font-size: 40px;
    font-weight: 800;
    color: var(--teal);
  }
  .perf-highlight .ph-label {
    font-size: 18px;
    color: var(--gray-700);
    line-height: 1.4;
  }

  /* ── RISKS SECTION ── */
  .risks-section {
    padding: 52px 64px;
    border-bottom: 2px solid var(--gray-200);
    background: linear-gradient(180deg, var(--off-white) 0%, var(--white) 100%);
  }
  .risks-section h2 {
    font-size: 36px;
    font-weight: 700;
    color: var(--accent);
    margin-bottom: 28px;
    padding-bottom: 16px;
    border-bottom: 4px solid var(--accent);
    display: inline-block;
  }
  .risks-grid {
    display: grid;
    grid-template-columns: repeat(5, 1fr);
    gap: 20px;
  }
  .risk-card {
    padding: 28px 24px;
    background: var(--white);
    border-radius: 12px;
    border: 2px solid var(--accent-border);
    border-top: 5px solid var(--accent);
    position: relative;
  }
  .risk-card .risk-number {
    font-size: 48px;
    font-weight: 900;
    color: var(--accent);
    opacity: 0.2;
    position: absolute;
    top: 8px;
    right: 16px;
    line-height: 1;
  }
  .risk-card h3 {
    font-size: 21px;
    font-weight: 700;
    color: var(--accent);
    margin-bottom: 12px;
    line-height: 1.3;
  }
  .risk-card p {
    font-size: 17px;
    line-height: 1.6;
    color: var(--gray-700);
  }

  /* ── FRAMEWORK SECTION ── */
  .framework-section {
    padding: 52px 64px;
    border-bottom: 2px solid var(--gray-200);
  }
  .framework-section h2 {
    font-size: 36px;
    font-weight: 700;
    color: var(--navy);
    margin-bottom: 28px;
    padding-bottom: 16px;
    border-bottom: 4px solid var(--teal);
    display: inline-block;
  }
  .framework-steps {
    display: grid;
    grid-template-columns: repeat(5, 1fr);
    gap: 0;
    position: relative;
  }
  .framework-step {
    text-align: center;
    padding: 28px 20px;
    position: relative;
  }
  .framework-step::after {
    content: '';
    position: absolute;
    top: 52px;
    right: -10px;
    width: 20px;
    height: 4px;
    background: var(--teal);
    z-index: 1;
  }
  .framework-step:last-child::after { display: none; }
  .step-circle {
    width: 64px;
    height: 64px;
    border-radius: 50%;
    background: var(--teal);
    color: var(--white);
    font-size: 28px;
    font-weight: 800;
    display: flex;
    align-items: center;
    justify-content: center;
    margin: 0 auto 20px;
    position: relative;
    z-index: 2;
  }
  .framework-step h3 {
    font-size: 20px;
    font-weight: 700;
    color: var(--navy);
    margin-bottom: 10px;
    line-height: 1.3;
  }
  .framework-step p {
    font-size: 16px;
    line-height: 1.5;
    color: var(--gray-500);
  }

  /* ── CONSENSUS BANNER ── */
  .consensus-banner {
    padding: 40px 64px;
    background: var(--navy);
    color: var(--white);
    text-align: center;
  }
  .consensus-banner p {
    font-size: 26px;
    font-weight: 400;
    line-height: 1.6;
    max-width: 85%;
    margin: 0 auto;
  }
  .consensus-banner strong {
    font-weight: 700;
    color: var(--teal-light);
  }

  /* ── FOOTER ── */
  .footer {
    padding: 32px 64px;
    background: var(--gray-100);
    display: flex;
    justify-content: space-between;
    align-items: center;
  }
  .footer .ref-text {
    font-size: 16px;
    color: var(--gray-500);
    line-height: 1.6;
    max-width: 75%;
  }
  .footer .venue-badge {
    font-size: 18px;
    font-weight: 600;
    color: var(--navy);
    background: var(--white);
    padding: 12px 24px;
    border-radius: 8px;
    border: 2px solid var(--gray-300);
  }

  /* ── ANTV CHART CONTAINER ── */
  #perf-chart {
    width: 100%;
    height: 360px;
  }

  /* SVG icon helpers */
  .icon-svg {
    width: 24px;
    height: 24px;
    fill: var(--teal);
  }
</style>
</head>
<body>
<div class="poster">

  <!-- HEADER -->
  <div class="header">
    <div class="conference">Medical AI &amp; Digital Health Conference 2024</div>
    <h1>Large Language Models in Medicine:<br>Opportunities, Risks, and the Path Forward</h1>
    <div class="subtitle">A comprehensive review of how large language models are transforming clinical practice, medical research, and healthcare delivery &mdash; along with the critical challenges that must be addressed.</div>
  </div>

  <!-- METRICS ROW -->
  <div class="metrics-row">
    <div class="metric-card navy">
      <div class="value">&gt;90%</div>
      <div class="label">GPT-4 USMLE Score</div>
      <div class="context">Exceeded passing threshold on all three steps of the USMLE</div>
    </div>
    <div class="metric-card teal">
      <div class="value">500+</div>
      <div class="label">PubMed Articles (2023)</div>
      <div class="context">Peer-reviewed publications on LLMs in medicine in 2023 alone</div>
    </div>
    <div class="metric-card accent">
      <div class="value">Up to 30%</div>
      <div class="label">Hallucination Rate</div>
      <div class="context">Fabricated medical references or inaccurate clinical information</div>
    </div>
    <div class="metric-card teal">
      <div class="value">$10.5B</div>
      <div class="label">Projected Market (2030)</div>
      <div class="context">Global healthcare LLM market projected by 2030</div>
    </div>
  </div>

  <!-- CONTENT -->
  <div class="content">

    <!-- OVERVIEW + APPLICATIONS -->
    <div class="two-col">
      <div class="panel overview-panel">
        <h2>What Are LLMs and Why Do They Matter?</h2>
        <p>Large language models (LLMs) such as <strong>GPT-4</strong>, <strong>Med-PaLM 2</strong>, and <strong>LLaMA</strong> have rapidly entered the healthcare landscape, demonstrating remarkable capabilities in understanding and generating medical text.</p>
        <br>
        <p>A landmark review published in <em>Nature Medicine</em> (July 2023) examined how these foundation models &mdash; trained on vast corpora of text data &mdash; are poised to reshape clinical practice, biomedical research, and medical education.</p>
        <br>
        <p>The pace of adoption has been extraordinary: over 500 peer-reviewed publications appeared in 2023 alone, and the global healthcare LLM market is projected to reach $10.5 billion by 2030.</p>
      </div>

      <div class="panel">
        <h2>Key Clinical &amp; Research Applications</h2>
        <div class="app-grid">
          <div class="app-item">
            <div class="app-icon">
              <svg viewBox="0 0 24 24" class="icon-svg"><path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8l-6-6zm-1 1.5L18.5 9H13V3.5zM6 20V4h5v7h7v9H6zm2-7h8v1.5H8V13zm0 3h8v1.5H8V16z"/></svg>
            </div>
            <div class="app-body">
              <h3>Clinical Documentation</h3>
              <div class="app-desc">Automated note generation, discharge summaries</div>
              <span class="maturity">Pilot Deployments</span>
            </div>
          </div>
          <div class="app-item">
            <div class="app-icon">
              <svg viewBox="0 0 24 24" class="icon-svg"><path d="M12 2C6.48 2 2 6.48 2 12s4.48 10 10 10 10-4.48 10-10S17.52 2 12 2zm-2 15l-5-5 1.41-1.41L10 14.17l7.59-7.59L19 8l-9 9z"/></svg>
            </div>
            <div class="app-body">
              <h3>Diagnostic Support</h3>
              <div class="app-desc">Differential diagnosis, radiology report interpretation</div>
              <span class="maturity">Research Stage</span>
            </div>
          </div>
          <div class="app-item">
            <div class="app-icon">
              <svg viewBox="0 0 24 24" class="icon-svg"><path d="M20 2H4c-1.1 0-2 .9-2 2v18l4-4h14c1.1 0 2-.9 2-2V4c0-1.1-.9-2-2-2zm0 14H6l-2 2V4h16v12z"/></svg>
            </div>
            <div class="app-body">
              <h3>Patient Communication</h3>
              <div class="app-desc">Answering questions, simplifying medical jargon</div>
              <span class="maturity">Early Adoption</span>
            </div>
          </div>
          <div class="app-item">
            <div class="app-icon">
              <svg viewBox="0 0 24 24" class="icon-svg"><path d="M12 3L1 9l4 2.18v6L12 21l7-3.82v-6l2-1.09V17h2V9L12 3zm6.82 6L12 12.72 5.18 9 12 5.28 18.82 9zM17 15.99l-5 2.73-5-2.73v-3.72L12 15l5-2.73v3.72z"/></svg>
            </div>
            <div class="app-body">
              <h3>Medical Education</h3>
              <div class="app-desc">Exam preparation, case-based learning, tutoring</div>
              <span class="maturity">Active Use</span>
            </div>
          </div>
          <div class="app-item">
            <div class="app-icon">
              <svg viewBox="0 0 24 24" class="icon-svg"><path d="M9.5 2A7.5 7.5 0 0 1 17 9.5c0 1.7-.6 3.3-1.5 4.6l5.1 5.1-1.4 1.4-5.1-5.1A7.5 7.5 0 1 1 9.5 2zm0 2A5.5 5.5 0 1 0 15 9.5 5.5 5.5 0 0 0 9.5 4z"/></svg>
            </div>
            <div class="app-body">
              <h3>Biomedical Research</h3>
              <div class="app-desc">Literature synthesis, hypothesis generation, protocol drafting</div>
              <span class="maturity">Emerging</span>
            </div>
          </div>
        </div>
      </div>
    </div>

    <!-- PERFORMANCE BENCHMARKS -->
    <div class="performance-section">
      <h2>Performance Benchmarks &amp; Evidence</h2>
      <div class="perf-container">
        <div class="perf-chart-area">
          <div id="perf-chart" class="chart-wrapper"></div>
        </div>
        <div class="perf-text">
          <p>LLM performance on standardized medical examinations has been a key area of evaluation, demonstrating rapid improvement across model generations.</p>
          <div class="perf-highlight">
            <div class="ph-value">&gt;90%</div>
            <div class="ph-label">GPT-4 on all three USMLE steps, substantially exceeding the ~60% passing threshold</div>
          </div>
          <div class="perf-highlight">
            <div class="ph-value">86.5%</div>
            <div class="ph-label">Med-PaLM 2 on MedQA, approaching expert physician-level performance</div>
          </div>
          <p>These results suggest LLMs encode substantial medical knowledge, though performance on real-world clinical scenarios remains less well characterized.</p>
        </div>
      </div>
    </div>

    <!-- RISKS & LIMITATIONS -->
    <div class="risks-section">
      <h2>Risks, Limitations, &amp; Ethical Concerns</h2>
      <div class="risks-grid">
        <div class="risk-card">
          <div class="risk-number">1</div>
          <h3>Hallucinations</h3>
          <p>LLMs fabricate plausible-sounding but incorrect medical information, including fake citations. Rates up to 30% in medical Q&amp;A tasks.</p>
        </div>
        <div class="risk-card">
          <div class="risk-number">2</div>
          <h3>Bias &amp; Equity</h3>
          <p>Models may perpetuate or amplify biases in training data, leading to disparities in care recommendations across demographic groups.</p>
        </div>
        <div class="risk-card">
          <div class="risk-number">3</div>
          <h3>Privacy</h3>
          <p>Patient data in prompts may be transmitted to external servers, raising serious HIPAA and GDPR compliance concerns.</p>
        </div>
        <div class="risk-card">
          <div class="risk-number">4</div>
          <h3>Lack of Clinical Validation</h3>
          <p>Most LLM evaluations rely on multiple-choice benchmarks rather than prospective clinical trials.</p>
        </div>
        <div class="risk-card">
          <div class="risk-number">5</div>
          <h3>Over-reliance Risk</h3>
          <p>Clinicians may develop automation bias, accepting LLM outputs without sufficient critical appraisal.</p>
        </div>
      </div>
    </div>

    <!-- FRAMEWORK -->
    <div class="framework-section">
      <h2>A Framework for Responsible Deployment</h2>
      <div class="framework-steps">
        <div class="framework-step">
          <div class="step-circle">1</div>
          <h3>Rigorous Prospective Evaluation</h3>
          <p>In diverse clinical settings before deployment</p>
        </div>
        <div class="framework-step">
          <div class="step-circle">2</div>
          <h3>Human-in-the-Loop Design</h3>
          <p>Ensuring clinician oversight of all LLM-generated outputs</p>
        </div>
        <div class="framework-step">
          <div class="step-circle">3</div>
          <h3>Transparent Reporting</h3>
          <p>Of model limitations, training data sources, and known failure modes</p>
        </div>
        <div class="framework-step">
          <div class="step-circle">4</div>
          <h3>Equity Audits</h3>
          <p>To assess differential performance across patient populations</p>
        </div>
        <div class="framework-step">
          <div class="step-circle">5</div>
          <h3>Regulatory Alignment</h3>
          <p>With evolving FDA, EMA, and WHO guidance on AI-based medical devices</p>
        </div>
      </div>
    </div>

    <!-- CONSENSUS BANNER -->
    <div class="consensus-banner">
      <p>LLMs hold <strong>transformative potential</strong> for medicine, but their deployment must be guided by <strong>evidence, equity, and robust governance</strong> to ensure patient safety.</p>
    </div>

  </div>

