const { chromium } = require('playwright');
const path = require('path');

(async () => {
  const browser = await chromium.launch();
  const page = await browser.newPage();

  // Set viewport to match the poster width; height will be determined by content
  await page.setViewportSize({ width: 2480, height: 3510 });

  // Load the HTML file
  const htmlPath = path.resolve('/app/output/poster.html');
  await page.goto(`file://${htmlPath}`, { waitUntil: 'networkidle' });

  // Wait for fonts and AntV chart to render
  await page.waitForTimeout(3000);

  // Wait for the AntV chart to finish rendering
  await page.waitForFunction(() => {
    const chartEl = document.querySelector('#perf-chart');
    if (!chartEl) return true; // If chart doesn't exist, proceed anyway
    return chartEl.querySelector('svg') !== null || chartEl.querySelector('canvas') !== null;
  }, { timeout: 15000 }).catch(() => console.log('Chart render timeout, proceeding...'));

  // Extra wait for animations and font rendering
  await page.waitForTimeout(2000);

  // Take a full-page screenshot at 2x device scale for high resolution
  await page.screenshot({
    path: '/app/output/final_poster.png',
    fullPage: true,
    type: 'png',
  });

  console.log('Poster rendered to /app/output/final_poster.png');
  await browser.close();
})();

