const { chromium } = require('playwright');
const path = require('path');

(async () => {
  const browser = await chromium.launch();
  const context = await browser.newContext({
    deviceScaleFactor: 2,
  });
  const page = await context.newPage();

  // Set viewport
  await page.setViewportSize({ width: 2480, height: 3510 });

  // Load the HTML file
  const htmlPath = path.resolve('/app/output/poster.html');
  await page.goto(`file://${htmlPath}`, { waitUntil: 'load' });

  // Wait for AntV script to load
  await page.waitForTimeout(2000);

  // Wait for the AntV chart to render (SVG or canvas inside the container)
  try {
    await page.waitForFunction(() => {
      const chartEl = document.querySelector('#perf-chart');
      if (!chartEl) return true;
      const hasSvg = chartEl.querySelector('svg') !== null;
      const hasCanvas = chartEl.querySelector('canvas') !== null;
      return hasSvg || hasCanvas;
    }, { timeout: 20000 });
    console.log('Chart detected in DOM');
  } catch (e) {
    console.log('Chart render timeout, proceeding anyway');
  }

  // Wait for fonts and any remaining rendering
  await page.waitForTimeout(3000);

  // Take full-page screenshot
  await page.screenshot({
    path: '/app/output/final_poster.png',
    fullPage: true,
    type: 'png',
  });

  console.log('Poster rendered to /app/output/final_poster.png');
  await browser.close();
})();

