const { chromium } = require('playwright');
const path = require('path');

(async () => {
  const browser = await chromium.launch();
  const page = await browser.newPage();
  await page.setViewportSize({ width: 1200, height: 800 });

  const htmlPath = path.resolve('/app/output/poster.html');
  page.on('console', msg => console.log('PAGE:', msg.text()));
  page.on('pageerror', err => console.log('ERROR:', err.message));

  await page.goto(`file://${htmlPath}`, { waitUntil: 'load' });
  await page.waitForTimeout(5000);

  // Check what's in the chart container
  const chartInfo = await page.evaluate(() => {
    const el = document.querySelector('#perf-chart');
    if (!el) return { exists: false };
    return {
      exists: true,
      innerHTML: el.innerHTML.substring(0, 500),
      childCount: el.children.length,
      width: el.offsetWidth,
      height: el.offsetHeight,
      firstChildTag: el.children[0]?.tagName,
    };
  });
  console.log('Chart info:', JSON.stringify(chartInfo, null, 2));

  // Check if AntVInfographic is defined
  const antvInfo = await page.evaluate(() => {
    return {
      defined: typeof AntVInfographic !== 'undefined',
      hasInfographic: typeof AntVInfographic?.Infographic !== 'undefined',
    };
  });
  console.log('AntV info:', JSON.stringify(antvInfo));

  await browser.close();
})();

