const { chromium } = require('playwright');
const path = require('path');

(async () => {
  const browser = await chromium.launch();
  const context = await browser.newContext({ deviceScaleFactor: 2 });
  const page = await context.newPage();
  await page.setViewportSize({ width: 2480, height: 3510 });

  const htmlPath = path.resolve('/app/output/poster.html');
  await page.goto(`file://${htmlPath}`, { waitUntil: 'load' });
  await page.waitForTimeout(2000);

  // Get section positions
  const sections = await page.evaluate(() => {
    const result = {};
    const selectors = {
      'header': '.header',
      'metrics-row': '.metrics-row',
      'overview': '.overview-panel',
      'applications': '.panel:not(.overview-panel)',
      'performance': '.performance-section',
      'risks': '.risks-section',
      'framework': '.framework-section',
      'banner': '.consensus-banner',
      'footer': '.footer',
      'chart-svg': '.perf-chart-area svg',
    };
    for (const [name, sel] of Object.entries(selectors)) {
      const el = document.querySelector(sel);
      if (el) {
        const rect = el.getBoundingClientRect();
        result[name] = {
          top: Math.round(rect.top),
          bottom: Math.round(rect.bottom),
          left: Math.round(rect.left),
          right: Math.round(rect.right),
          width: Math.round(rect.width),
          height: Math.round(rect.height),
        };
      } else {
        result[name] = null;
      }
    }
    return result;
  });

  console.log('Section positions (in CSS pixels, multiply by 2 for image pixels):');
  for (const [name, pos] of Object.entries(sections)) {
    if (pos) {
      console.log(`  ${name}: top=${pos.top} bottom=${pos.bottom} height=${pos.height}`);
    } else {
      console.log(`  ${name}: NOT FOUND`);
    }
  }

  // Take the screenshot
  await page.screenshot({
    path: '/app/output/final_poster.png',
    fullPage: true,
    type: 'png',
  });

  console.log('\nPoster rendered.');
  await browser.close();
})();

