    text-align: center;
  }
  .consensus-banner p {
    font-size: 24px; font-weight: 400; line-height: 1.6; max-width: 88%; margin: 0 auto;
  }
  .consensus-banner strong {
    font-weight: 700; color: var(--teal-light);
  }

  /* ── FOOTER ── */
  .footer {
    padding: 28px 60px;
    background: var(--gray-100);
    display: flex; justify-content: space-between; align-items: center;
  }
  .footer .ref-text {
    font-size: 15px; color: var(--gray-500); line-height: 1.6; max-width: 78%;
  }
  .footer .venue-badge {
    font-size: 17px; font-weight: 600; color: var(--navy);
    background: var(--white); padding: 10px 20px;
    border-radius: 8px; border: 2px solid var(--gray-300);
  }
</style>
